    27	    @Transactional(propagation = Propagation.MANDATORY)
    28	    public boolean take(List<OrderItem> items) {
    29	        List<OrderItem> sorted = sortedBySku(items);
    30	        Map<String, Integer> stock = products.lockStock(sorted.stream().map(OrderItem::sku).toList());
    31	        boolean available = sorted.stream()
    32	                .allMatch(item -> stock.getOrDefault(item.sku(), 0) >= item.quantity());
    33	        if (!available) {
    34	            return false;
    35	        }
    36	        sorted.forEach(item -> products.changeStock(item.sku(), -item.quantity()));
    37	        return true;
    38	    }
    40	    @Transactional(propagation = Propagation.MANDATORY)
    41	    public void giveBack(List<OrderItem> items) {
    42	        List<OrderItem> sorted = sortedBySku(items);
    43	        products.lockStock(sorted.stream().map(OrderItem::sku).toList());
    44	        sorted.forEach(item -> products.changeStock(item.sku(), item.quantity()));
    45	    }
    47	    private static List<OrderItem> sortedBySku(List<OrderItem> items) {
    48	        return items.stream().sorted(Comparator.comparing(OrderItem::sku)).toList();
