    30	    @Override
    31	    public ShippingQuote quote(ShippingRequest request) {
    32	        int weightGrams = request.weightKg().multiply(GRAMS_PER_KG).setScale(0, RoundingMode.CEILING).intValueExact();
    33	        CarrierQuote quote;
    34	        try {
